cases.yaml:
apiVersion: iaf.platform/v1
kind: Workflow
metadata: { name: vm-info, title: VM info, noun: vm, verb: read, owner: team-compute, version: 1.0.0 }
api:
  input:
    type: object
    required: [vmId]
    $defs: { id: { type: string, minLength: 1 } }
    properties:
      vmId: { type: string }
      note: { $ref: "#/$defs/id" }
      self: { $ref: "#" }
policy:
  rbac: [ops]
workflow:
  do:
    - getVm:
        name: Get VM
        call: provider
        with: { provider: vsphere, action: vm.get, input: { id: "{{ $input.vmId }}" } }
